UPDATE clubJoin
SET clubJoin_result = 1
WHERE clubJoin_num = #{applyNum}

UPDATE clubJoin
SET clubJoin_result = 0,
clubJoin_reason = #{rejectReason}
WHERE clubJoin_num = #{applyNum}

